+
+    fn walk<'a>(&'a self, callback: &mut impl FnMut(&'a Self)) {
+        callback(self);
+        match self {
+            Self::Variable(_)
+            | Self::Bound(_)
+            | Self::NamedNode(_)
+            | Self::Literal(_)
+            | Self::Exists(_) => (),
+            Self::UnaryPlus(i) | Self::UnaryMinus(i) | Self::Not(i) => i.walk(callback),
+            Self::Or(l, r)
+            | Self::And(l, r)
+            | Self::Equal(l, r)
+            | Self::SameTerm(l, r)
+            | Self::Greater(l, r)
+            | Self::GreaterOrEqual(l, r)
+            | Self::Less(l, r)
+            | Self::LessOrEqual(l, r)
+            | Self::Add(l, r)
+            | Self::Subtract(l, r)
+            | Self::Multiply(l, r)
+            | Self::Divide(l, r) => {
+                l.walk(callback);
+                r.walk(callback);
+            }
+            Self::If(c, l, r) => {
+                c.walk(callback);
+                l.walk(callback);
+                r.walk(callback);
+            }
+            Self::Coalesce(l) | Self::FunctionCall(_, l) => {
+                for e in l {
+                    e.walk(callback);
+                }
+            }
+            Self::In(l, r) => {
+                l.walk(callback);
+                for e in r {
+                    e.walk(callback);
+                }
+            }
+        }
+    }
+
+    fn lookup_used_variable<'a>(&'a self, callback: &mut impl FnMut(&'a Variable)) {
+        self.walk(&mut |e| {
+            if let Self::Variable(v) | Self::Bound(v) = e {
+                callback(v)
+            } else if let Self::Exists(p) = e {
+                p.lookup_used_variables(callback)
+            }
+        })
+    }
 }

